import {useRef,useState} from 'react';import {createRoot} from 'react-dom/client';
import {WorkloadCapacityPlanning} from '../../components/workload-capacity-planning';
import {createWorkloadIllustration} from '../../lib/workload-capacity-illustration';
import {actionBinding} from '../../lib/home-action-drafts';
import type {WorkloadCapacityInput} from '../../lib/workload-capacity';
import {appPageFromSearch,appPageHref} from '../../lib/app-page-url';
import {appNavigationSections,appPageMetadata} from '../../lib/app-navigation';
function Harness(){const [route,setRoute]=useState('workload-capacity'),[context,setContext]=useState({goalId:'synthetic-goal',goal:'Review synthetic ticket workload',datasetToken:'legacy-v1:0',revision:1}),mode=useRef('normal'),release=useRef<null|(()=>void)>(null);
 async function prepare(c:WorkloadCapacityInput['identity']){if(mode.current==='interrupted')await new Promise<void>(resolve=>{release.current=resolve;});const binding=await actionBinding(c.goalId,c.goal,{datasetToken:c.datasetToken,sources:[]},{origin:'illustrative-OPS-CLIENT-ticket-v1'}),i=createWorkloadIllustration(c,{datasetToken:c.datasetToken,binding});if(mode.current==='part-month')i.options[0].draft.inputs.capacity!.input.arrivalDate='2027-01-15';if(mode.current==='multiple')i.managers.push(structuredClone(i.managers[0]));return i;}
 return <main className="mx-auto max-w-6xl"><nav aria-label="Synthetic test navigation" className="flex flex-wrap gap-2">{['Planning Overview','Workload & Capacity Planning'].map(name=><button className="min-h-11 rounded border p-2" key={name} onClick={()=>{const page=name==='Planning Overview'?'planning-overview':'workload-capacity';history.pushState({},'',appPageHref(location,page));setRoute(appPageFromSearch(location.search));}}>{name}</button>)}<button className="min-h-11 rounded border p-2" onClick={()=>setContext({...context,goalId:context.goalId==='other-goal'?'synthetic-goal':'other-goal',goal:'Another synthetic goal'})}>Switch synthetic goal</button><button className="min-h-11 rounded border p-2" onClick={()=>setContext({...context,datasetToken:'other:1'})}>Switch synthetic dataset</button>{['normal','part-month','multiple','interrupted'].map(m=><button key={m} className="min-h-11 rounded border p-2" onClick={()=>{mode.current=m;}}>Fixture {m}</button>)}<button className="min-h-11 rounded border p-2" onClick={()=>release.current?.()}>Release interrupted fixture</button></nav>{route==='workload-capacity'?<WorkloadCapacityPlanning context={context} prepare={prepare}/>:<h1>Planning Overview</h1>}<output data-testid="navigation" hidden>{JSON.stringify({listed:appNavigationSections.find(s=>s.key==='strategy')!.pages.includes('workload-capacity'),label:appPageMetadata['workload-capacity'].label})}</output><output data-testid="saved" hidden>{JSON.stringify({goals:'unchanged',plans:'unchanged',measurements:'unchanged'})}</output></main>;
}createRoot(document.getElementById('root')!).render(<Harness/>);
